#!/usr/bin/env node
// Generates the smartcrop.js reference crops of the attention strategy tests (SmartCropOracleTest).
//
// Downloads smartcrop.js 2.0.5 (MIT) from the npm registry's CDN mirror into the conformance cache,
// builds deterministic synthetic RGBA pictures (a skin-toned ellipse, a saturated patch, a textured
// area and a smooth gradient, placed differently in each picture), runs smartcrop.crop on each with
// prescaling off (the Java test feeds the same pixels to the analysis directly), and writes into
// core/src/test/resources/com/github/auties00/smalt/image/ops/smartcrop:
//   <name>.bin : the raw RGBA input
//   cases.tsv  : name, width, height, crop width, crop height, and the top crop's x and y
//
// Usage: node tools/testdata/smartcrop-oracle.js
'use strict';
const fs = require('fs');
const os = require('os');
const path = require('path');
const https = require('https');

const VERSION = '2.0.5';
const ROOT = path.resolve(__dirname, '..', '..');
const OUT = path.join(ROOT, 'core/src/test/resources/com/github/auties00/smalt/image/ops/smartcrop');
const CACHE = process.env.SMALT_CONFORMANCE_CACHE || path.join(os.homedir(), '.smalt', 'cache', 'conformance');

function download(url, file) {
  return new Promise((resolve, reject) => {
    https.get(url, response => {
      if (response.statusCode !== 200) {
        reject(new Error(url + ': HTTP ' + response.statusCode));
        return;
      }
      const chunks = [];
      response.on('data', chunk => chunks.push(chunk));
      response.on('end', () => {
        fs.mkdirSync(path.dirname(file), {recursive: true});
        fs.writeFileSync(file, Buffer.concat(chunks));
        resolve(file);
      });
    }).on('error', reject);
  });
}

function picture(width, height, seed, layout) {
  const data = new Uint8ClampedArray(width * height * 4);
  let state = BigInt(seed) * 0x9E3779B97F4A7C15n & 0xFFFFFFFFFFFFFFFFn;
  const next = () => {
    state = (state * 6364136223846793005n + 1442695040888963407n) & 0xFFFFFFFFFFFFFFFFn;
    return Number(state >> 56n);
  };
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const p = (y * width + x) * 4;
      let r = 90 + (x * 60 / width | 0);
      let g = 100 + (y * 50 / height | 0);
      let b = 110;
      const dx = (x - layout.skinX) / layout.skinR;
      const dy = (y - layout.skinY) / (layout.skinR * 1.3);
      if (dx * dx + dy * dy < 1) {
        r = 224; g = 172; b = 140;
      }
      if (x >= layout.patchX && x < layout.patchX + 14 && y >= layout.patchY && y < layout.patchY + 10) {
        r = 30; g = 200; b = 40;
      }
      if (x >= layout.textureX && x < layout.textureX + 20 && ((x + y) & 3) === 0) {
        r = g = b = 20;
      }
      const n = next();
      data[p] = r + (n & 7) - 4;
      data[p + 1] = g + ((n >> 3) & 7) - 4;
      data[p + 2] = b;
      data[p + 3] = 255;
    }
  }
  return data;
}

async function main() {
  const file = path.join(CACHE, 'smartcrop-' + VERSION + '.js');
  if (!fs.existsSync(file)) {
    await download('https://cdn.jsdelivr.net/npm/smartcrop@' + VERSION + '/smartcrop.js', file);
  }
  const smartcrop = require(file);
  const iop = {
    open: image => Promise.resolve(image),
    resample: () => Promise.reject(new Error('prescaling is off')),
    getData: image => Promise.resolve(image),
  };
  const cases = [
    {name: 'skin-left', width: 96, height: 64, aspect: [1, 1], layout: {skinX: 20, skinY: 30, skinR: 9, patchX: 70, patchY: 8, textureX: 200}},
    {name: 'patch-right', width: 96, height: 64, aspect: [3, 4], layout: {skinX: -50, skinY: 0, skinR: 1, patchX: 74, patchY: 40, textureX: 60}},
    {name: 'texture-middle', width: 120, height: 48, aspect: [1, 1], layout: {skinX: -50, skinY: 0, skinR: 1, patchX: 300, patchY: 0, textureX: 48}},
    {name: 'portrait', width: 48, height: 96, aspect: [4, 3], layout: {skinX: 24, skinY: 70, skinR: 8, patchX: 300, patchY: 0, textureX: 300}},
    {name: 'wide-crop', width: 128, height: 64, aspect: [16, 9], layout: {skinX: 100, skinY: 20, skinR: 7, patchX: 8, patchY: 50, textureX: 30}},
  ];
  fs.mkdirSync(OUT, {recursive: true});
  const lines = ['# name\twidth\theight\tcropWidth\tcropHeight\tx\ty (generated by tools/testdata/smartcrop-oracle.js, smartcrop.js ' + VERSION + ')'];
  for (let i = 0; i < cases.length; i++) {
    const test = cases[i];
    const data = picture(test.width, test.height, i + 1, test.layout);
    fs.writeFileSync(path.join(OUT, test.name + '.bin'), Buffer.from(data.buffer));
    const image = new smartcrop.ImgData(test.width, test.height, data);
    const result = await smartcrop.crop(image, {width: test.aspect[0], height: test.aspect[1], prescale: false, imageOperations: iop});
    const crop = result.topCrop;
    lines.push([test.name, test.width, test.height, crop.width, crop.height, crop.x, crop.y].join('\t'));
  }
  fs.writeFileSync(path.join(OUT, 'cases.tsv'), lines.join('\n') + '\n');
  console.log('wrote ' + cases.length + ' cases to ' + OUT);
}

main().catch(error => {
  console.error(error);
  process.exit(1);
});
